from pathlib import Path
import pandas as pd
from reportlab.platypus import Paragraph,PageBreak,Spacer

def appendix(root,styles,table):
    p=Path(root)/'results'/'kpis'
    metrics=pd.read_csv(p/'performance_metrics.csv')
    carried=metrics[metrics.strategy.eq('carry')].set_index('sample')
    boot=pd.read_csv(p/'block_bootstrap_intervals.csv')
    inf=pd.read_csv(p/'hac_inference.csv')
    tags=['development','validation_2025'];s=[carried.loc[t] for t in tags]
    P=lambda x:Paragraph(x,styles['BodySmall'])
    H=lambda x:Paragraph(x,styles['SubBlue'])
    f=[PageBreak(),Paragraph('Performance KPIs: what to report',styles['TitleBlue']),P('Sharpe must identify its cash benchmark. A ratio calculated against idle cash describes return per unit of observed volatility, but does not establish value above the opportunity cost of capital. Daily volatility also excludes rare venue and stablecoin loss events.'),H('Carry strategy: matched 24-hour observations')]
    rows=[['Metric','2022-2024','Feb-Dec 2025']]
    for label,func in [('Total net return',lambda r:f'{r.total_return:.2%}'),('Annualized return (CAGR)',lambda r:f'{r.cagr:.2%}'),('Volatility from daily returns',lambda r:f'{r.annual_volatility:.2%}'),('Volatility from hourly returns',lambda r:f'{r.hourly_annual_volatility:.2%}'),('Sharpe above SOFR, daily returns',lambda r:f'{r.sofr_excess_sharpe:.2f}'),('Sharpe above SOFR, hourly returns',lambda r:f'{r.hourly_sofr_excess_sharpe:.2f}'),('Sharpe above zero, hourly returns',lambda r:f'{r.hourly_zero_rf_ratio:.2f}'),('Maximum hourly drawdown',lambda r:f'{r.maximum_hourly_drawdown:.2%}'),('Daily return observations',lambda r:str(int(r.observations))) ]:rows.append([label,*[func(r) for r in s]])
    f+=[table(rows,[225,137,137]),Spacer(1,10),P('Metrics use 01:00 UTC marks exactly 24 hours apart, with entry costs in the first daily return and final exit costs in the last. This differs from the midnight sampling on earlier P&L pages; final cash is unchanged. Maximum hourly drawdown is the more conservative observed drawdown measure. One development spot hour is flagged stale; the maximum hourly drawdown occurs at a different, fresh observation.'),H('Definitions'),P('Sharpe = sqrt(365.25) x mean(daily strategy return - daily cash return) / standard deviation(daily excess return). Annual volatility = daily strategy-return standard deviation x sqrt(365.25). CAGR compounds terminal wealth over elapsed years; it is not an arithmetic mean. The 11-month annualized figure is descriptive and is not an extra year of observations.'),P('Hourly volatility and ratios use sqrt(365.25 x 24) annualization. The daily zero-cash ratios of 11.11 and 9.43 fall to 3.32 and 3.44 with hourly returns. Thus the largest number is highly sampling-dependent. Serial dependence also affects annualization; HAC and block-bootstrap inference below account for dependence when testing means. No simple frequency-scaled ratio fully captures venue tail risk.'),H('Historical cash benchmark'),P('Historical SOFR rates come directly from the New York Fed. The cash proxy retrospectively accrues each effective-day rate on ACT/360, carrying the previous business-day rate across weekends and holidays. It is an accrual proxy, not the official SOFR Index, an investable deposit account, or guaranteed USDT income. USD/USDT parity is assumed for comparison. The strategy itself receives no added collateral interest. SOFR is not used by any trading signal.')]
    f +=[PageBreak(),Paragraph('Benchmarks and statistical evidence',styles['TitleBlue']),H('Net cumulative returns over matching dates')]
    rows=[['Benchmark','2022-2024','Feb-Dec 2025']]
    for name,label in [('carry','Continuous funding carry'),('buy_hold','BTC buy-and-hold'),('momentum20','20-day momentum, long / cash')]:
        rr=metrics[metrics.strategy.eq(name)].set_index('sample')
        rows.append([label,*[f'{rr.loc[t].total_return:.2%}' for t in tags]])
    rows.append(['Historical SOFR cash proxy',*[f'{r.benchmark_sofr_total_return:.2%}' for r in s]])
    f +=[table(rows,[225,137,137]),Spacer(1,9),P('Spot benchmarks use the same 10bp fee, 2bp slippage and 0.001 BTC research lot. Buy-and-hold invests once and closes at the end. Momentum holds BTC when the price change across 20 calendar days is positive; its signal uses the prior day 00:00 price and executes at 01:00 the following day, at least 25 hours later. Cash while flat earns zero. No parameter search is used. These are descriptive benchmarks, not newly validated optimal strategies.'),P('Risk differs materially: buy-and-hold maximum daily drawdown was 66.66% in development and 32.03% in the later sample, compared with carry hourly drawdowns of 1.12% and 0.11%. Higher BTC returns in one sample are not a comparison at equal risk. Carry beat the two spot benchmarks in the later realized sample, but neither paired daily-mean comparison establishes statistically reliable outperformance.'),H('Is excess return statistically established?')]
    rows=[['Carry minus historical SOFR','2022-2024','Feb-Dec 2025']]
    for label,func in [('Annualized mean daily excess',lambda t:f'{inf.query("sample == @t and benchmark == \'sofr\' and hac_lag == 30").iloc[0].mean_annual:.2%}'),('95% block-bootstrap interval',lambda t:None),('HAC two-sided p-value',lambda t:f'{inf.query("sample == @t and benchmark == \'sofr\' and hac_lag == 30").iloc[0].hac_p_two_sided:.3g}')]:
        if label.startswith('95%'):
            vals=[]
            for t in tags:
                r=boot[(boot['sample']==t)&boot.benchmark.eq('sofr')&boot.block_days.eq(30)].iloc[0]
                vals.append(f'[{r.mean_ci_low:.2%}, {r.mean_ci_high:.2%}]')
        else:vals=[func(t) for t in tags]
        rows.append([label,*vals])
    f +=[table(rows,[225,137,137]),Spacer(1,9),P('Intervals use 10,000 circular moving-block bootstrap draws, 30-day blocks and seed 16. HAC tests use 30 lags. The cash-excess conclusion is unchanged with 7-day and 90-day choices: development intervals include zero; the later intervals are wholly negative. Intervals concern annualized arithmetic mean daily excess returns, not a confidence interval for the realized cumulative return or CAGR.'),P('Within this backtest, positive returns above idle cash are supported, but development excess return above SOFR is not. The later sample shows underperformance against the cash proxy under the dependence-aware tests. These are exploratory conditional results. Stationarity, bootstrap and covariance assumptions can fail across regimes; limited tail events and price/execution errors are not repaired by a low p-value. Paired benchmark comparisons are not adjusted for multiple testing, and no broad alpha claim is made.'),H('Use on a CV'),P('Lead with the self-financing ledger, funding and margin modeling, frozen later-period evaluation and cost stress. Quantify 1.96% net over the 11-month later sample, 0.11% maximum observed hourly drawdown and 168.01 USDT profit under doubled costs on 10,000 USDT. Label all figures as simulated. Do not advertise a Sharpe of 9.43 without its zero-cash benchmark; the cash-excess Sharpe is negative. This remains a research/backtesting project with no demonstrated premium over cash.'),Paragraph('Sources: New York Fed SOFR; Lo (2002), Financial Analysts Journal; Newey-West (1987), Econometrica. Eleven checks pass. Reproduce with kpis.py; full results are in results/kpis/.',styles['TinyNote'])]
    return f
